parameters.jsCode:
// Take top 8 Hacker News IDs
const ids = $input.first().json.slice(0, 8);
return ids.map(id => ({ json: { id } }));

// Aggregate Hacker News stories and GitHub Repositories
const hnItems = $("Get Story Details").all().map(item => ({
  title: item.json.title,
  url: item.json.url || `https://news.ycombinator.com/item?id=${item.json.id}`,
  score: item.json.score || 0,
  source: 'Hacker News'
}));

const ghData = $("Fetch GitHub Trending Repos").first().json;
const ghItems = (ghData.items || []).slice(0, 5).map(repo => ({
  name: repo.full_name,
  description: repo.description || 'Open source tool',
  url: repo.html_url,
  stars: repo.stargazers_count,
  source: 'GitHub Trending'
}));

return [{
  json: {
    raw_stories: hnItems,
    github_candidates: ghItems
  }
}];

parameters.jsonBody:
={
  "model": "openai/gpt-oss-120b",
  "messages": [
    {
      "role": "system",
      "content": "You are a Principal Systems Architect writing an internal engineering brief. STRICT RULES: FORBIDDEN WORDS: revolutionary, game-changer, delve, tapestry, testament, unleash, foster, pivotal, paramount, in today's fast-paced. ZERO MARKETING HYPE: State exact technical functions, protocols, performance metrics, and architectural trade-offs. Return a valid JSON matching this schema: { \"top_stories\": [ { \"headline\": \"title\", \"summary\": \"2-sentence technical summary\", \"architectural_impact\": \"latency/memory/concurrency tradeoff\", \"category\": \"Systems/AI/Cloud\", \"url\": \"link\" } ], \"github_gem\": { \"repo_name\": \"owner/repo\", \"description\": \"1 punchy technical sentence\", \"quickstart\": \"terminal command\", \"technical_utility\": \"why use it\", \"url\": \"link\" }, \"system_design_card\": { \"topic\": \"Concept Name\", \"core_problem\": \"Bottleneck it solves\", \"mechanism_breakdown\": [\"Step 1\", \"Step 2\"], \"production_case_study\": \"e.g. Discord/Netflix production example\" }, \"terminal_power_tip\": { \"command\": \"unix command\", \"use_case\": \"why it saves debugging time\" } }"
    },
    {
      "role": "user",
      "content": JSON.stringify($json)
    }
  ],
  "response_format": {"type": "json_object"},
  "temperature": 0.1
}

parameters.jsCode:
const responseRaw = $input.first().json.choices[0].message.content;
let data;
try {
  data = JSON.parse(responseRaw);
} catch (e) {
  data = {};
}

const today = new Date().toLocaleDateString('en-US', {
  weekday: 'long',
  year: 'numeric',
  month: 'short',
  day: 'numeric'
});

let storiesHtml = '';
for (const item of (data.top_stories || []).slice(0, 3)) {
  storiesHtml += `
    <div style="background-color: #ffffff; border: 1px solid #e5e7eb; border-radius: 6px; padding: 16px; margin-bottom: 14px;">
      <div style="font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; color: #475569; margin-bottom: 6px;">${item.category || 'Systems'}</div>
      <div style="font-size: 16px; font-weight: 700; color: #0f172a; margin-bottom: 6px; line-height: 1.3;">
        <a href="${item.url}" style="color: #0f172a; text-decoration: none;">${item.headline}</a>
      </div>
      <div style="font-size: 13.5px; color: #334155; line-height: 1.5; margin-bottom: 10px;">${item.summary}</div>
      <div style="background-color: #f8fafc; border-left: 3px solid #0284c7; padding: 8px 12px; font-size: 12.5px; color: #0369a1; font-weight: 600;">
        ⚙️ <strong>Architectural Impact:</strong> ${item.architectural_impact}
      </div>
    </div>
  `;
}

const gem = data.github_gem || {};
const gemHtml = `
  <div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 6px; padding: 14px; margin-bottom: 14px;">
    <div style="font-size: 11px; font-weight: 700; text-transform: uppercase; color: #475569; margin-bottom: 4px;">🛠️ Open-Source Tooling Spotlight</div>
    <div style="font-size: 15px; font-weight: 700; color: #0f172a; margin-bottom: 4px;">
      <a href="${gem.url || '#'}" style="color: #0284c7; text-decoration: none;">${gem.repo_name}</a>
    </div>
    <div style="font-size: 13px; color: #475569; margin-bottom: 8px;">${gem.description}</div>
    <div style="background-color: #0f172a; color: #38bdf8; font-family: ui-monospace, Menlo, monospace; padding: 6px 10px; border-radius: 4px; font-size: 12px; margin-bottom: 6px;">
      ${gem.quickstart}
    </div>
    <div style="font-size: 12px; color: #64748b;"><strong>Technical Utility:</strong> ${gem.technical_utility}</div>
  </div>
`;

const sd = data.system_design_card || {};
const bullets = (sd.mechanism_breakdown || []).map(b => `<li style="margin-bottom: 3px;">${b}</li>`).join('');
const sdHtml = `
  <div style="background-color: #f0f9ff; border: 1px solid #bae6fd; border-radius: 6px; padding: 14px; margin-bottom: 14px;">
    <div style="font-size: 11px; font-weight: 700; text-transform: uppercase; color: #0284c7; margin-bottom: 4px;">🧠 System Design Architecture Card</div>
    <div style="font-size: 15px; font-weight: 700; color: #0369a1; margin-bottom: 4px;">${sd.topic}</div>
    <div style="font-size: 13px; color: #075985; margin-bottom: 6px;"><strong>Core Bottleneck:</strong> ${sd.core_problem}</div>
    <ul style="margin: 0 0 6px 0; padding-left: 18px; font-size: 12.5px; color: #0f172a; line-height: 1.4;">
      ${bullets}
    </ul>
    <div style="font-size: 12px; color: #0369a1; font-weight: 600;"><strong>Production Case Study:</strong> ${sd.production_case_study}</div>
  </div>
`;

const tip = data.terminal_power_tip || {};
const tipHtml = `
  <div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 6px; padding: 12px; margin-bottom: 16px;">
    <div style="font-size: 11px; font-weight: 700; text-transform: uppercase; color: #475569; margin-bottom: 4px;">⚡ Systems & Debugging Recipe</div>
    <code style="background-color: #0f172a; color: #38bdf8; font-family: ui-monospace, Menlo, monospace; padding: 3px 6px; border-radius: 4px; font-size: 12px; display: inline-block; margin-bottom: 4px;">${tip.command}</code>
    <div style="font-size: 12.5px; color: #334155;">${tip.use_case}</div>
  </div>
`;

const emailHtml = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background-color: #f3f4f6; margin: 0; padding: 18px;">
  <div style="max-width: 600px; margin: 0 auto; background-color: #ffffff; border-radius: 8px; overflow: hidden; border: 1px solid #e5e7eb;">
    <div style="background-color: #0f172a; padding: 24px 20px; color: #ffffff;">
      <div style="font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: #94a3b8; margin-bottom: 4px;">ENGINEERING EXECUTIVE BRIEFING</div>
      <div style="font-size: 20px; font-weight: 800; color: #ffffff; margin-bottom: 4px;">Morning Tech Pulse</div>
      <div style="font-size: 12px; color: #cbd5e1;">${today} • Prepared for Vivek Kanugula</div>
    </div>
    <div style="padding: 20px; background-color: #fafafa;">
      <div style="font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; color: #64748b; margin-bottom: 12px;">1. Core Technical Developments</div>
      ${storiesHtml}
      ${gemHtml}
      ${sdHtml}
      ${tipHtml}
      <div style="text-align: center; padding-top: 12px; border-top: 1px solid #e5e7eb; font-size: 11px; color: #94a3b8;">
        Curated autonomously via Groq Llama-3.3-70B • Distributed via n8n & Gmail SMTP
      </div>
    </div>
  </div>
</body>
</html>
`;

const firstHeadline = (data.top_stories && data.top_stories[0]) ? data.top_stories[0].headline : 'Daily Briefing';

return [{
  json: {
    subject: `Morning Tech Pulse: ${firstHeadline} [${today}]`,
    htmlContent: emailHtml
  }
}];
